const heur = $('Code in JavaScript1').first().json;
let decisiones = [];
const cur = $json || {};
if (Array.isArray(cur.decisiones)) decisiones = cur.decisiones;
else {
  const raw = (cur.content && cur.content.parts && cur.content.parts[0]) ? cur.content.parts[0].text : null;
  if (typeof raw === 'string') { try { const p = JSON.parse(raw); if (p && Array.isArray(p.decisiones)) decisiones = p.decisiones; } catch (e) {} }
}

const asignaciones = (heur.asignaciones || []).map(a => ({ ...a }));
const equipo = (heur.input_original && heur.input_original.equipo) || [];
const empById = Object.fromEntries(equipo.map(e => [String(e.persona_id), e]));
const byTarea = Object.fromEntries(asignaciones.map(a => [String(a.tarea_id), a]));
const empatesById = Object.fromEntries((heur.empates || []).map(e => [String(e.tarea_id), e]));

let aplicados = 0;
for (const d of decisiones) {
  const a = byTarea[String(d.tarea_id)];
  const emp = empatesById[String(d.tarea_id)];
  if (!a || !emp || a.estado_asignacion !== 'asignada') continue;
  const cand = (emp.candidatos || []).find(c => String(c.persona_id) === String(d.persona_id));
  if (!cand) continue;
  const distinto = String(a.persona_id) !== String(d.persona_id);
  if (distinto) {
    const p = empById[String(d.persona_id)];
    if (!p) continue;
    a.persona_id = p.persona_id; a.persona = p.nombre; a.rol = p.rol; a.seniority = p.seniority;
    a.skills_match = (cand.cubre || []).join(', ');
  }
  a.motivo = distinto
    ? 'Desempate por LLM (cambió la elección del heurístico)'
    : 'Desempate por LLM (confirmó la elección del heurístico)';
  aplicados++;
}

const horas = {}, tareasP = {};
for (const a of asignaciones) {
  if (a.estado_asignacion !== 'asignada') continue;
  const id = String(a.persona_id);
  horas[id] = (horas[id] || 0) + Number(a.horas_estimadas || 0);
  (tareasP[id] = tareasP[id] || []).push(a.tarea_id);
}
const resumen_personas = (heur.resumen_personas || []).map(p => {
  const id = String(p.persona_id);
  const cap = Number(p.capacidad_horas_semana || 0);
  const asign = horas[id] || 0;
  return { ...p, horas_asignadas: asign, horas_libres: cap - asign, porcentaje_ocupacion: cap > 0 ? Math.round(asign / cap * 100) : 0, num_tareas: (tareasP[id] || []).length, tareas: (tareasP[id] || []).join(', ') };
});

return [{ json: { ...heur, asignaciones, resumen_personas, desempate_llm: aplicados } }];
